  "claim": {
    "component_id": "C049.main",
    "value": "Accounts still awaiting their publication opportunity cannot yet establish failure to publish.",
    "scope": "A temporal limit while the relevant publication opportunity remains pending.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies the pending-opportunity condition and the limit on failure attribution."
    }
  },
  "signal_basis": {
    "component_id": "C049.signal_basis",
    "value": "Document intended roster timing, define an observation window covering the intended publication opportunity, and follow unresolved accounts while separately reporting those whose opportunity has not yet occurred.",
    "scope": "Assessment of first publication relative to the relevant opportunity; intended dates may change, and the observations are proposed rather than completed findings.",
